(31261, 'Numbers 34:8', 'Numbers', 34, 8, 'له هغې وروسته به هغه د حمات د غاښي په لاره صدد ته ورسیږي.', 'له هغې وروسته به هغه د حمات د غاشی په لاره صدد ته ورسیزی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Numbers_34_8.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237836, 1761237836),
(31262, 'Numbers 34:9', 'Numbers', 34, 9, 'د صدد څخه به سرحد په ختیځ کې زفرون ته ورسیږي او په حصرعینان کې به پای ته ورسیږي.', 'د صدد چخه به سرحد په ختیج کې زفرون ته ورسیزی او په حصرعینان کې به پای ته ورسیزی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Numbers_34_9.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237836, 1761237836),
(31263, 'Numbers 34:10', 'Numbers', 34, 10, 'ختیځ سرحد به په شمال کې په حصرعینان کې پیل شي، بیا به جنوب خواته شفام', 'ختیج سرحد به په شمال کې په حصرعینان کې پیل شی، بیا به جنوب خواته شفام', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Numbers_34_10.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237836, 1761237836),
(31264, 'Numbers 34:11', 'Numbers', 34, 11, 'او ربله ته ورسیږي چې د عین په ختیځې خوا کې دی. د هغه ځای څخه به هغه د جنوب په لور د جلیل د بحیرې ختیځو غونډیو ته ورسیږي،', 'او ربله ته ورسیزی چې د عین په ختیجې خوا کې دی. د هغه جای چخه به هغه د جنوب په لور د جلیل د بحیرې ختیجو غوندیو ته ورسیزی،', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Numbers_34_11.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237836, 1761237836),
(31265, 'Numbers 34:12', 'Numbers', 34, 12, 'بیا به د اردن د سیند په لاره د مړې بحیرې د شمالي برخې اخرني سرته ورسیږي. کومه ځمکه چې د هغو څلورو سرحدونو په منځ کې وي، هغه به ستاسو شي.»', 'بیا به د اردن د سیند په لاره د مرې بحیرې د شمالی برخې اخرنی سرته ورسیزی. کومه جمکه چې د هغو چلورو سرحدونو په منج کې وی، هغه به ستاسو شی.»', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Numbers_34_12.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237836, 1761237836),
(31266, 'Numbers 34:13', 'Numbers', 34, 13, 'نو موسی اسراییلیانو ته داسې امر وکړ: «دا هغه ځمکه ده چې تاسو به یې د پچې اچولو له مخې تر لاسه کړئ، یعنې هغه ځمکه چې څښتن د نهه نیمو قبیلو دپاره ټاکلې ده.', 'نو موسی اسراییلیانو ته داسې امر وکر: «دا هغه جمکه ده چې تاسو به یې د پچې اچولو له مخې تر لاسه کری، یعنې هغه جمکه چې چشتن د نهه نیمو قبیلو دپاره تاکلې ده.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Numbers_34_13.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237836, 1761237836),
(31267, 'Numbers 34:14', 'Numbers', 34, 14, 'د روبین، جاد او د منسي نیمې قبیلې خپله ځمکه تر لاسه کړې ده چې د هغوی د کورنیو له مخې وېشل شوې ده.', 'د روبین، جاد او د منسی نیمې قبیلې خپله جمکه تر لاسه کرې ده چې د هغوی د کورنیو له مخې وېشل شوې ده.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Numbers_34_14.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237836, 1761237836),
(31268, 'Numbers 34:15', 'Numbers', 34, 15, 'دا اریحا ته مخامخ د اردن د سیند په ختیځ کې ده.»', 'دا اریحا ته مخامخ د اردن د سیند په ختیج کې ده.»', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Numbers_34_15.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237836, 1761237836),
(31269, 'Numbers 34:16', 'Numbers', 34, 16, 'څښتن موسی ته وویل:', 'چشتن موسی ته وویل:', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Numbers_34_16.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237836, 1761237836),
(31270, 'Numbers 34:17', 'Numbers', 34, 17, '«العازار کاهن او د نون زوی یوشع به خلکو ته ځمکه ووېشي.', '«العازار کاهن او د نون زوی یوشع به خلکو ته جمکه ووېشی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Numbers_34_17.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237836, 1761237836),
(31271, 'Numbers 34:18', 'Numbers', 34, 18, 'د هرې قبیلې څخه یو یو مشر وټاکه چې د هغوی سره د ځمکې په وېشلو کې مرسته وکړي.', 'د هرې قبیلې چخه یو یو مشر وتاکه چې د هغوی سره د جمکې په وېشلو کې مرسته وکری.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Numbers_34_18.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237836, 1761237836),
(31272, 'Numbers 34:29', 'Numbers', 34, 29, 'دا هغه کسان دي چې څښتن ورباندې حکم وکړ چې د اسراییلیانو دپاره د ځمکې په وېشلو کې د العازار او یوشع سره مرسته وکړي.', 'دا هغه کسان دی چې چشتن ورباندې حکم وکر چې د اسراییلیانو دپاره د جمکې په وېشلو کې د العازار او یوشع سره مرسته وکری.', 'OT', 'afghan2023', 'afghan', '', '', 1761237836, 1761237836),
(31273, 'Exodus 21:1', 'Exodus', 21, 1, 'څښتن موسی ته وویل: «دا هغه قوانین دي چې ته یې باید اسراییلیانو ته ورکړې:', 'چشتن موسی ته وویل: «دا هغه قوانین دی چې ته یې باید اسراییلیانو ته ورکرې:', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Exodus_21_1.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237836, 1761237836),
(31274, 'Exodus 21:2', 'Exodus', 21, 2, 'که چېرې تاسو یو عبرانی غلام په بیه واخلئ، هغه دې شپږ کاله ستاسو خدمت وکړي. خو په اووم کال به پرته له دې چې څه بیه ورڅخه واخیستل شي، هغه دې ازاد کړای شي.', 'که چېرې تاسو یو عبرانی غلام په بیه واخلی، هغه دې شپز کاله ستاسو خدمت وکری. خو په اووم کال به پرته له دې چې چه بیه ورچخه واخیستل شی، هغه دې ازاد کرای شی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Exodus_21_2.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237836, 1761237836),
(31275, 'Exodus 21:3', 'Exodus', 21, 3, 'که چېرې په هغه وخت کې چې هغه ستاسو غلام شوی ؤ واده یې نه ؤ کړی، نو هغه به د تګ په وخت کې خپله ښځه د ځان سره نه بیایي. خو که چېرې په هغه وخت کې چې هغه ستاسو غلام شو واده یې کړی ؤ، هغه به خپله ښځه هم د ځان سره بوځي.', 'که چېرې په هغه وخت کې چې هغه ستاسو غلام شوی و واده یې نه و کری، نو هغه به د تګ په وخت کې خپله شجه د جان سره نه بیایی. خو که چېرې په هغه وخت کې چې هغه ستاسو غلام شو واده یې کری و، هغه به خپله شجه هم د جان سره بوجی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Exodus_21_3.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237836, 1761237836),
(31276, 'Exodus 21:4', 'Exodus', 21, 4, 'که چېرې بادار یې ورته ښځه وکړي او هغه ښځه ورته زامن یا لورګانې وزېږوي، هغه ښځه او د هغې ماشومان د بادار کیږي او یوازې هغه سړی دې ازاد شي.', 'که چېرې بادار یې ورته شجه وکری او هغه شجه ورته زامن یا لورګانې وزېزوی، هغه شجه او د هغې ماشومان د بادار کیزی او یوازې هغه سری دې ازاد شی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Exodus_21_4.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237836, 1761237836),
(31277, 'Exodus 21:5', 'Exodus', 21, 5, 'خو که چېرې هغه غلام داسې اعلان وکړي چې زه د خپل بادار او د خپلې ښځې او ماشومانو سره مینه لرم او نه غواړم چې ازاد شم،', 'خو که چېرې هغه غلام داسې اعلان وکری چې زه د خپل بادار او د خپلې شجې او ماشومانو سره مینه لرم او نه غوارم چې ازاد شم،', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Exodus_21_5.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237836, 1761237836),
(31278, 'Exodus 21:6', 'Exodus', 21, 6, 'بیا به یې خپل بادار د عبادت ځای ته بوځي. هغه دې هلته د دروازې یا د دروازې د چوکاټ په مخکې ودروي او په ستنه باندې دې د هغه غوږ سوری کړي. بیا به دا سړی ټول عمر د هغه غلام وي.', 'بیا به یې خپل بادار د عبادت جای ته بوجی. هغه دې هلته د دروازې یا د دروازې د چوکات په مخکې ودروی او په ستنه باندې دې د هغه غوز سوری کری. بیا به دا سری تول عمر د هغه غلام وی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Exodus_21_6.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237836, 1761237836),
(31279, 'Exodus 21:7', 'Exodus', 21, 7, 'که چېرې یو سړی خپله لور د یوې وینځې په توګه خرڅوي، هغه دې د نارینه غلامانو په شان ازاده نه شي.', 'که چېرې یو سری خپله لور د یوې وینجې په توګه خرچوی، هغه دې د نارینه غلامانو په شان ازاده نه شی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Exodus_21_7.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237836, 1761237836),
(31280, 'Exodus 21:8', 'Exodus', 21, 8, 'که چېرې هغه په یو داسې کس باندې خرڅه شي چې داسې نیت ولري چې هغه خپله ښځه کړي، خو هغه یې خوښه نه شي، نو بیا دې هغه بېرته د خپل پلار له خوا په بیه واخیستل شي. د هغې بادار هغه په پردیو خلکو باندې نه شي خرڅولی، ځکه چې دا کار د هغې سره خیانت شمېرل کیږي.', 'که چېرې هغه په یو داسې کس باندې خرچه شی چې داسې نیت ولری چې هغه خپله شجه کری، خو هغه یې خوشه نه شی، نو بیا دې هغه بېرته د خپل پلار له خوا په بیه واخیستل شی. د هغې بادار هغه په پردیو خلکو باندې نه شی خرچولی، جکه چې دا کار د هغې سره خیانت شمېرل کیزی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Exodus_21_8.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237836, 1761237836),
(31281, 'Exodus 21:9', 'Exodus', 21, 9, 'که چېرې یو سړی یوه وینځه واخلي چې خپل زوی ته یې وکړي، نو د هغې سره دې لکه د خپلې لور په شان چلند کوي.', 'که چېرې یو سری یوه وینجه واخلی چې خپل زوی ته یې وکری، نو د هغې سره دې لکه د خپلې لور په شان چلند کوی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Exodus_21_9.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237836, 1761237836),
(31282, 'Exodus 21:10', 'Exodus', 21, 10, 'که چېرې یو سړی دوهم واده وکړي، نو باید لومړنۍ ښځه د خوړو، کالیو او د واده د حقونو څخه بې برخې نه کړي.', 'که چېرې یو سری دوهم واده وکری، نو باید لومرنی شجه د خورو، کالیو او د واده د حقونو چخه بې برخې نه کری.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Exodus_21_10.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237836, 1761237836),
(31283, 'Exodus 21:11', 'Exodus', 21, 11, 'که چېرې هغې ته دا درې شیان نه برابروي، نو باید ازاده یې کړي او هېڅ بیه دې وانخلي.', 'که چېرې هغې ته دا درې شیان نه برابروی، نو باید ازاده یې کری او هېچ بیه دې وانخلی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Exodus_21_11.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237836, 1761237836),
(31284, 'Exodus 21:12', 'Exodus', 21, 12, 'که چېرې څوک یو بل کس داسې ووهي چې هغه مړ شي، نو هغه کس باید ووژل شي.', 'که چېرې چوک یو بل کس داسې ووهی چې هغه مر شی، نو هغه کس باید ووژل شی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Exodus_21_12.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237836, 1761237836),
(31285, 'Exodus 21:13', 'Exodus', 21, 13, 'خو که چېرې هغه دا کار په قصد سره نه وي کړی، خو د خدای له خوا ورته پېښه شي، نو هغه دې داسې ځای ته وتښتي چې زه یې ټاکم.', 'خو که چېرې هغه دا کار په قصد سره نه وی کری، خو د خدای له خوا ورته پېشه شی، نو هغه دې داسې جای ته وتشتی چې زه یې تاکم.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Exodus_21_13.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237836, 1761237836),
(31286, 'Exodus 21:14', 'Exodus', 21, 14, 'خو که چېرې یو سړی دسیسه جوړه کړي او په قصدي توګه بل سړی ووژني حتی که چېرې هغه د خوندي پاتې کېدلو دپاره زما د قربانۍ ځای ته هم وتښتي، باید ووژل شي.', 'خو که چېرې یو سری دسیسه جوره کری او په قصدی توګه بل سری ووژنی حتی که چېرې هغه د خوندی پاتې کېدلو دپاره زما د قربانی جای ته هم وتشتی، باید ووژل شی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Exodus_21_14.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237836, 1761237836),
(31287, 'Exodus 21:15', 'Exodus', 21, 15, 'هرڅوک چې خپل پلار یا خپله مور ووهي، هغه باید ووژل شي.', 'هرچوک چې خپل پلار یا خپله مور ووهی، هغه باید ووژل شی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Exodus_21_15.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237836, 1761237836),
(31288, 'Exodus 21:16', 'Exodus', 21, 16, 'هرڅوک چې یو بل کس وتښتوي او هغه خرڅ کړي یا تر هغه وخته پورې ورسره وي چې هغه ونیول شي، هغه باید ووژل شي.', 'هرچوک چې یو بل کس وتشتوی او هغه خرچ کری یا تر هغه وخته پورې ورسره وی چې هغه ونیول شی، هغه باید ووژل شی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Exodus_21_16.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237836, 1761237836),
