(31335, 'Exodus 16:20', 'Exodus', 16, 20, 'خو د هغوی څخه ځینو موسی ته غوږ ونه نیوه او لږه یې وساتله. په راتلونکي سهار هغې چینجي وکړل او بد بوی یې کاوه، نو موسی هغوی ته په قهر شو.', 'خو د هغوی چخه جینو موسی ته غوز ونه نیوه او لزه یې وساتله. په راتلونکی سهار هغې چینجی وکرل او بد بوی یې کاوه، نو موسی هغوی ته په قهر شو.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Exodus_16_20.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237836, 1761237836),
(31336, 'Exodus 16:21', 'Exodus', 16, 21, 'هر سهار هرچا د خپلې اړتیا له مخې خواړه راټولول او کله به چې لمر ګرمېده، نو څه چې په ځمکه باندې پاتې کېدل هغه به ویلي کېدل.', 'هر سهار هرچا د خپلې ارتیا له مخې خواره راتولول او کله به چې لمر ګرمېده، نو چه چې په جمکه باندې پاتې کېدل هغه به ویلی کېدل.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Exodus_16_21.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237836, 1761237836),
(31337, 'Exodus 16:22', 'Exodus', 16, 22, 'په شپږمه ورځ هغوی دوه چنده راټوله کړه، یعنې څلور لیتره د هر یو کس دپاره. نو د قوم ټول مشران راغلل او موسی یې خبر کړ.', 'په شپزمه ورج هغوی دوه چنده راتوله کره، یعنې چلور لیتره د هر یو کس دپاره. نو د قوم تول مشران راغلل او موسی یې خبر کر.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Exodus_16_22.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237836, 1761237836),
(31338, 'Exodus 16:23', 'Exodus', 16, 23, 'موسی هغوی ته وویل: «څښتن حکم کړی دی چې سبا د سبت یعنې د ارام کولو سپېڅلې ورځ ده چې څښتن ته وقف شوې ده. نن هرڅه چې غواړئ پاخه یې کړئ او هرڅه چې غواړئ ویې ایشوئ. هرڅه چې پاتې کیږي هغه د سهار دپاره وساتئ.»', 'موسی هغوی ته وویل: «چشتن حکم کری دی چې سبا د سبت یعنې د ارام کولو سپېچلې ورج ده چې چشتن ته وقف شوې ده. نن هرچه چې غواری پاخه یې کری او هرچه چې غواری ویې ایشوی. هرچه چې پاتې کیزی هغه د سهار دپاره وساتی.»', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Exodus_16_23.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237836, 1761237836),
(31339, 'Exodus 16:24', 'Exodus', 16, 24, 'څنګه چې موسی امر کړی ؤ، څه چې پاتې شول هغوی تر راتلونکې ورځې پورې وساتل او هغه بوی او چینجي ونه کړل.', 'چنګه چې موسی امر کری و، چه چې پاتې شول هغوی تر راتلونکې ورجې پورې وساتل او هغه بوی او چینجی ونه کرل.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/exodus_16_24.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237836, 1761237836),
(31340, 'Exodus 16:25', 'Exodus', 16, 25, 'موسی وویل: «دا نن وخورئ، ځکه چې نن د سبت یعنې د ارام کولو ورځ ده چې څښتن ته وقف شوې ده او تاسو به دباندې په ځمکه باندې خواړه ونه مومئ.', 'موسی وویل: «دا نن وخوری، جکه چې نن د سبت یعنې د ارام کولو ورج ده چې چشتن ته وقف شوې ده او تاسو به دباندې په جمکه باندې خواره ونه مومی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/exodus_16_25.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237836, 1761237836),
(31341, 'Exodus 16:26', 'Exodus', 16, 26, 'تاسو باید شپږ ورځې خواړه راټول کړئ، خو په اوومه ورځ چې د سبت ورځ ده هېڅ شی به نه وي.»', 'تاسو باید شپز ورجې خواره راتول کری، خو په اوومه ورج چې د سبت ورج ده هېچ شی به نه وی.»', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/exodus_16_26.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237836, 1761237836),
(31342, 'Exodus 16:27', 'Exodus', 16, 27, 'بیاهم ځینې خلک په اوومه ورځ د خوړو د راټولولو دپاره لاړل، خو هغوی هېڅ څه ونه موندل.', 'بیاهم جینې خلک په اوومه ورج د خورو د راتولولو دپاره لارل، خو هغوی هېچ چه ونه موندل.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/exodus_16_27.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237836, 1761237836),
(31343, 'Exodus 16:28', 'Exodus', 16, 28, 'بیا څښتن موسی ته وویل: «تاسو به ترڅه وخته پورې زما د حکمونو او قوانینو څخه سرغړونه کوئ؟', 'بیا چشتن موسی ته وویل: «تاسو به ترچه وخته پورې زما د حکمونو او قوانینو چخه سرغرونه کوی؟', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/exodus_16_28.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237836, 1761237836),
(31344, 'Exodus 16:29', 'Exodus', 16, 29, 'یاد ساتئ چې زه څښتن یم او ما تاسو ته د ارام کولو دپاره یوه ورځ درکړې ده. همدا دلیل دی چې زه به په شپږمه ورځ تل د دوه ورځو خواړه درکوم. په اوومه ورځ دې هرڅوک په خپل کور کې پاتې شي او د هغه ځای څخه دې نه راوځي.»', 'یاد ساتی چې زه چشتن یم او ما تاسو ته د ارام کولو دپاره یوه ورج درکرې ده. همدا دلیل دی چې زه به په شپزمه ورج تل د دوه ورجو خواره درکوم. په اوومه ورج دې هرچوک په خپل کور کې پاتې شی او د هغه جای چخه دې نه راوجی.»', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/exodus_16_29.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237836, 1761237836),
(31345, 'Exodus 16:30', 'Exodus', 16, 30, 'نو خلکو په اوومه ورځ ارام وکړ.', 'نو خلکو په اوومه ورج ارام وکر.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/exodus_16_30.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237836, 1761237836),
(31346, 'Exodus 16:31', 'Exodus', 16, 31, 'دا خواړه د اسراییلو قوم د من په نوم یادول. هغه د دڼیا د دانو په شان وو، هغه سپین وو او د شاتو په شان خوند یې درلود.', 'دا خواره د اسراییلو قوم د من په نوم یادول. هغه د دنیا د دانو په شان وو، هغه سپین وو او د شاتو په شان خوند یې درلود.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/exodus_16_31.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237836, 1761237836),
(31347, 'Exodus 16:32', 'Exodus', 16, 32, 'موسی وویل: «څښتن حکم کړی دی چې دوه لیتره من واخلئ او د راتلونکو نسلونو دپاره یې وساتئ. نو هغوی به دا خواړه وویني چې هغه مې تاسو ته په هغه وخت کې په دښته کې درکړي وو چې کله مې د مصر څخه راوویستلئ.»', 'موسی وویل: «چشتن حکم کری دی چې دوه لیتره من واخلی او د راتلونکو نسلونو دپاره یې وساتی. نو هغوی به دا خواره ووینی چې هغه مې تاسو ته په هغه وخت کې په دشته کې درکری وو چې کله مې د مصر چخه راوویستلی.»', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/exodus_16_32.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237836, 1761237836),
(31348, 'Exodus 16:33', 'Exodus', 16, 33, 'موسی هارون ته وویل: «یو لوښی راواخله او دوه لیتره من په کې واچوه او د څښتن په حضور کې یې کېږده چې د راتلونکو نسلونو دپاره د یادګار په توګه وساتل شي.»', 'موسی هارون ته وویل: «یو لوشی راواخله او دوه لیتره من په کې واچوه او د چشتن په حضور کې یې کېزده چې د راتلونکو نسلونو دپاره د یادګار په توګه وساتل شی.»', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/exodus_16_33.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237836, 1761237836),
(31349, 'Exodus 16:34', 'Exodus', 16, 34, 'څنګه چې څښتن موسی ته حکم کړی ؤ، هارون هغه د لوظ د صندوق مخې ته کېښود چې وساتل شي.', 'چنګه چې چشتن موسی ته حکم کری و، هارون هغه د لوظ د صندوق مخې ته کېشود چې وساتل شی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/exodus_16_34.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237836, 1761237836),
(31350, 'Exodus 16:35', 'Exodus', 16, 35, 'اسراییلیانو څلوېښت کاله من وخوړ، تر هغې پورې چې هغوی د کنعان خاورې ته ورسېدل او هلته ځای په ځای شول.', 'اسراییلیانو چلوېشت کاله من وخور، تر هغې پورې چې هغوی د کنعان خاورې ته ورسېدل او هلته جای په جای شول.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/exodus_16_35.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237836, 1761237836),
